class MyLinkedList {
    private int[] val, next;
    private int head, size, cnt;
    public MyLinkedList() {
        val = new int[2001]; next = new int[2001];
        java.util.Arrays.fill(next, -1);
        head = 0; val[0] = -1; size = 0; cnt = 1;
    }
    public int get(int index) {
        if (index < 0 || index >= size) return -1;
        int cur = next[head];
        for (int i = 0; i < index; i++) cur = next[cur];
        return val[cur];
    }
    public void addAtHead(int v) { addAtIndex(0, v); }
    public void addAtTail(int v) { addAtIndex(size, v); }
    public void addAtIndex(int index, int v) {
        if (index < 0 || index > size) return;
        int prev = head;
        for (int i = 0; i < index; i++) prev = next[prev];
        int node = cnt++;
        val[node] = v;
        next[node] = next[prev];
        next[prev] = node;
        size++;
    }
    public void deleteAtIndex(int index) {
        if (index < 0 || index >= size) return;
        int prev = head;
        for (int i = 0; i < index; i++) prev = next[prev];
        next[prev] = next[next[prev]];
        size--;
    }
}
